from __future__ import annotationsfrom functools import lru_cachefrom pathlib import Pathimport joblibimport pandas as pdfrom ml_service.config import Config, load_configclass Predictor:    def __init__(self, config: Config | None = None) -> None:        self.config = config or load_config()        self._model = None    @property    def model(self):        if self._model is None:            path = Path(self.config.model_path)            if not path.exists():                raise FileNotFoundError(                    f"No model at {path}. Run `python -m ml_service.model.train` first."                )            self._model = joblib.load(path)        return self._model        def predict(self, features: list[float]) -> dict:        row = pd.DataFrame([features], columns=self.config.feature_names)        proba = self.model.predict_proba(row)[0]        idx = int(proba.argmax())        return {            "label": self.config.target_names[idx],            "label_index": idx,            "confidence": float(proba[idx]),            "probabilities": {                name: float(p)                for name, p in zip(self.config.target_names, proba)            },        }@lru_cache def get_predictor() -> Predictor:    return Predictor()